-- W-S2 Ordered Quantity = sum(quantity) over fact_order, dated by order_date
-- Generated by build_metric_sql.py; edit the generator, not this file.
WITH base AS (
  SELECT f.quantity, f.wwi_backorder_id,
         f.order_date, d.calendar_year, d.month_start_date, d.fiscal_year,
         c.category AS customer_category, c.customer AS customer_name,
         ci.sales_territory, ci.state_province,
         si.wwi_stock_item_id, si.stock_item,
         e.employee AS salesperson,
         p.employee AS picker
  FROM wwi.fact_order f
  JOIN wwi.dim_date d ON d.date_key = f.order_date
  JOIN wwi.dim_customer c ON c.customer_key = f.customer_key
  JOIN wwi.dim_city ci ON ci.city_key = f.city_key
  JOIN wwi.dim_stock_item si ON si.stock_item_key = f.stock_item_key
  JOIN wwi.dim_employee e ON e.employee_key = f.salesperson_key
  LEFT JOIN wwi.dim_employee p ON p.employee_key = f.picker_key
)
SELECT grain, measure, member_1, member_2, member_3, value
FROM (
  SELECT 'total' AS grain, 'W-S2' AS measure, CAST(NULL AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(quantity) AS value
  FROM base
  UNION ALL
  SELECT 'year' AS grain, 'W-S2' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(quantity) AS value
  FROM base
  GROUP BY calendar_year
  UNION ALL
  SELECT 'month' AS grain, 'W-S2' AS measure, CAST(month_start_date AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(quantity) AS value
  FROM base
  GROUP BY month_start_date
  UNION ALL
  SELECT 'day' AS grain, 'W-S2' AS measure, CAST(order_date AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(quantity) AS value
  FROM base
  GROUP BY order_date
  UNION ALL
  SELECT 'fiscal_year' AS grain, 'W-S2' AS measure, CAST(fiscal_year AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(quantity) AS value
  FROM base
  GROUP BY fiscal_year
  UNION ALL
  SELECT 'year_customer_category' AS grain, 'W-S2' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(customer_category AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(quantity) AS value
  FROM base
  GROUP BY calendar_year, customer_category
  UNION ALL
  SELECT 'year_customer' AS grain, 'W-S2' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(customer_name AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(quantity) AS value
  FROM base
  GROUP BY calendar_year, customer_name
  UNION ALL
  SELECT 'year_sales_territory' AS grain, 'W-S2' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(sales_territory AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(quantity) AS value
  FROM base
  GROUP BY calendar_year, sales_territory
  UNION ALL
  SELECT 'year_state_province' AS grain, 'W-S2' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(state_province AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(quantity) AS value
  FROM base
  GROUP BY calendar_year, state_province
  UNION ALL
  SELECT 'year_stock_item' AS grain, 'W-S2' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(stock_item AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(quantity) AS value
  FROM base
  GROUP BY calendar_year, stock_item
  UNION ALL
  SELECT 'year_salesperson' AS grain, 'W-S2' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(salesperson AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(quantity) AS value
  FROM base
  GROUP BY calendar_year, salesperson
  UNION ALL
  SELECT 'year_picker' AS grain, 'W-S2' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(picker AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(quantity) AS value
  FROM base
  GROUP BY calendar_year, picker
  UNION ALL
  SELECT 'year_stock_group' AS grain, 'W-S2' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(g.stock_group_name AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(quantity) AS value
  FROM base JOIN wwi.bridge_stock_item_group b ON b.wwi_stock_item_id = base.wwi_stock_item_id JOIN wwi.dim_stock_group g ON g.stock_group_id = b.stock_group_id
  GROUP BY calendar_year, g.stock_group_name
) r
ORDER BY grain, measure, member_1 NULLS FIRST, member_2 NULLS FIRST, member_3 NULLS FIRST
